function solarcity_intro_plain_text(html) {
    const box = document.createElement('div');
    box.innerHTML = html || '';
    return (box.innerText || box.textContent || '').replace(/\u00a0/g, ' ').trim();
}

function solarcity_intro_html(text, font_family, font_size, text_align) {
    const box = document.createElement('div');
    box.textContent = text || '';
    const safe = box.innerHTML;
    const paragraphs = safe.split(/\r?\n+/).map(line => line.trim()).filter(Boolean);
    const allowed_fonts = ['Cairo', 'Arial', 'Tahoma', 'Noto Naskh Arabic'];
    const family = allowed_fonts.includes(font_family) ? font_family : 'Cairo';
    const size = ['14', '16', '18', '20', '24'].includes(String(font_size)) ? String(font_size) : '16';
    const align = ['right', 'center', 'left'].includes(text_align) ? text_align : 'right';
    return '<div class="ql-editor read-mode">' +
        (paragraphs.length ? paragraphs : ['']).map(line =>
            '<p style="text-align: ' + align + ';"><span style="font-family: ' + family + '; font-size: ' + size + 'px;">' + line + '</span></p>'
        ).join('') +
        '</div>';
}

