function solarcity_normalize_quill_fonts(html) {
    const box = document.createElement('div');
    box.innerHTML = html || '';
    const classes = {
        'ql-font-cairo': 'Cairo',
        'ql-font-arial': 'Arial',
        'ql-font-tahoma': 'Tahoma',
        'ql-font-noto-naskh-arabic': 'Noto Naskh Arabic'
    };
    Object.entries(classes).forEach(([class_name, family]) => {
        box.querySelectorAll('.' + class_name).forEach((el) => {
            el.classList.remove(class_name);
            el.style.fontFamily = family;
        });
    });
    return box.innerHTML;
}

function solarcity_add_font_toolbar(frm) {
    const field = frm.get_field('custom_introduction_');
    if (!field || !field.$wrapper) return;
    const mount = () => {
        const toolbar = field.$wrapper.find('.ql-toolbar').first();
        if (!toolbar.length || toolbar.find('.solarcity-font-picker').length) return;
        try {
            const QuillClass = window.Quill || field.quill?.constructor;
            if (QuillClass) {
