                Font.whitelist = ['cairo', 'arial', 'tahoma', 'noto-naskh-arabic'];
                QuillClass.register(Font, true);
            }
        } catch (e) {}
        const select = document.createElement('select');
        select.className = 'solarcity-font-picker';
        select.title = 'Ø§Ø®ØªÙŠØ§Ø± Ù†ÙˆØ¹ Ø§Ù„Ø®Ø·';
