(function(){
  function mixed(doc){ return doc && doc.custom_type === 'Solar & Wells'; }
  function rowAmount(row){ if(row && row.parentfield==='custom_solar') return flt(row.qty||0)*flt(row.rate||0); return flt(row.amount||0) || (flt(row.qty||0)*flt(row.rate||0)); }
  function sum(rows){ return (rows||[]).reduce(function(total,row){ return total + rowAmount(row); },0); }
  function apply(frm){
    const doc=frm.doc;
    if(!mixed(doc)) return;
    const wellsTotal=sum(doc.items);
    const solarTotal=sum(doc.custom_solar);
    const gross=wellsTotal+solarTotal;
    const discount=flt(doc.discount_amount||doc.base_discount_amount||0);
    const net=Math.max(gross-discount,0);
    let running=net;
    let taxTotal=0;
    (doc.taxes||[]).forEach(function(tax){
      const rate=flt(tax.rate||0);
      const base=(tax.charge_type==='On Previous Row') ? running : net;
      let amount=base*rate/100;
      if(tax.add_deduct_tax==='Deduct') amount=-amount;
      tax.tax_amount=amount;
      tax.base_tax_amount=amount;
      running += amount;
      tax.total=running;
      tax.base_total=running;
      taxTotal += amount;
    });
    doc.total=gross;
    doc.base_total=gross;
    doc.net_total=net;
    doc.base_net_total=net;
    doc.total_taxes_and_charges=taxTotal;
    doc.base_total_taxes_and_charges=taxTotal;
    doc.grand_total=net+taxTotal;
    doc.base_grand_total=net+taxTotal;
    doc.rounded_total=net+taxTotal;
    doc.base_rounded_total=net+taxTotal;
    if(frm.refresh_field){
      frm.refresh_field('taxes');
      ['total','base_total','net_total','base_net_total','total_taxes_and_charges','base_total_taxes_and_charges','grand_total','base_grand_total','rounded_total','base_rounded_total'].forEach(function(field){ try{ frm.refresh_field(field); }catch(e){} });
    }
  }
  frappe.ui.form.on('Quotation',{
    refresh(frm){ apply(frm); },
    custom_type(frm){ apply(frm); },
    custom_solar_add(frm){ apply(frm); },
    custom_solar_remove(frm){ apply(frm); },
    discount_amount(frm){ apply(frm); },
    taxes_and_charges(frm){ apply(frm); },
    validate(frm){ apply(frm); }
  });
  frappe.ui.form.on('Quotation Item',{
    qty(frm,cdt,cdn){ const row=locals[cdt]&&locals[cdt][cdn]; if(row&&row.parentfield==='custom_solar') apply(frm); },
    rate(frm,cdt,cdn){ const row=locals[cdt]&&locals[cdt][cdn]; if(row&&row.parentfield==='custom_solar') apply(frm); },
    item_code(frm,cdt,cdn){ const row=locals[cdt]&&locals[cdt][cdn]; if(row&&row.parentfield==='custom_solar') apply(frm); }
  });
})();

